CustomField.formula:
IF( OR( ISBLANK(Parent.DateOfApplicationSubmission__c), Parent.DateOfApplicationSubmission__c < DATE(2026, 4, 1) ), "",
/* 1. Funding Validity Exceeded */ IF( AND( OR( NOT(ISBLANK(Treatment_Start_Date__c)), NOT(ISBLANK(Medication_Start_Date__c)) ), TODAY() > ADDMONTHS( IF( ISBLANK(Treatment_Start_Date__c), Medication_Start_Date__c, IF( ISBLANK(Medication_Start_Date__c), Treatment_Start_Date__c, IF( Treatment_Start_Date__c <= Medication_Start_Date__c, Treatment_Start_Date__c, Medication_Start_Date__c ) ) ), 6 ), TotalTreatmentandMedication__c > 0 ), "Funding Validity Exceeded",
/* 2. Started */ IF( AND( NOT(ISBLANK(Treatmentstartdate__c)), OR( NOT(ISBLANK(Treatment_Start_Date__c)), NOT(ISBLANK(Medication_Start_Date__c)) ), IF( ISBLANK(Treatment_Start_Date__c), Medication_Start_Date__c, IF( ISBLANK(Medication_Start_Date__c), Treatment_Start_Date__c, IF( Treatment_Start_Date__c <= Medication_Start_Date__c, Treatment_Start_Date__c, Medication_Start_Date__c ) ) ) <= ADDMONTHS(Treatmentstartdate__c, 3) ), "Started",
/* 3. Neither treatment nor medication started within 3 months */ IF( AND( ISBLANK(Treatment_Start_Date__c), ISBLANK(Medication_Start_Date__c), NOT(ISBLANK(Treatmentstartdate__c)), TODAY() > ADDMONTHS(Treatmentstartdate__c, 3) ), "Not Started 3 Months Timeline Exceeded",
"Not Started" ) ) ) )
